/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.integrationtest.feature.oauth.client.OidcFlowClient;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * Observable contract of the token endpoint: RFC 6749 §5.2 errors and anti-cache headers (1.4),
 * client authentication by registered method (0.9) and the revocation route (0.13).
 */
@Tag("oidc-flow")
@QuarkusTest
class TokenEndpointContractTest extends OidcIntegrationTestBase {

  private static final String BASIC =
      OidcFlowClient.basic(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

  private static void assertNoStore(Response response) {
    Assertions.assertEquals("no-store", response.getHeader("Cache-Control"));
    Assertions.assertEquals("no-cache", response.getHeader("Pragma"));
  }

  private static void assertError(Response response, int status, String error) {
    Assertions.assertEquals(status, response.statusCode(), response.asString());
    Assertions.assertEquals(error, response.jsonPath().getString("error"));
    Assertions.assertNotNull(response.jsonPath().getString("error_description"));
    assertNoStore(response);
    if (status == 401) {
      Assertions.assertNotNull(response.getHeader("WWW-Authenticate"));
    }
  }

  private Response password(String authorization, Map<String, String> extra) {
    Map<String, String> form = new java.util.HashMap<>(Map.of("grant_type", "password", "username",
        OidcTestFixtures.USERNAME, "password", OidcTestFixtures.PASSWORD, "scope", "openid"));
    form.putAll(extra);
    return client.token(OidcTestFixtures.TENANT, authorization, form);
  }

  // ── 1.4 errors and headers ────────────────────────────────────────────────

  @Test
  void success_isNeverCached() {
    Response response = password(BASIC, Map.of());

    Assertions.assertEquals(200, response.statusCode());
    assertNoStore(response);
  }

  @Test
  void missingGrantType_isInvalidRequest() {
    assertError(client.token(OidcTestFixtures.TENANT, BASIC, Map.of("scope", "openid")), 400,
        "invalid_request");
  }

  @Test
  void unknownGrantType_isUnsupportedGrantType() {
    assertError(client.token(OidcTestFixtures.TENANT, BASIC, Map.of("grant_type", "magic")), 400,
        "unsupported_grant_type");
  }

  @Test
  void grantNotAllowedToTheClient_isUnauthorizedClient() {
    clientStoreGateway.setAllowedGrants(List.of("authorization_code", "refresh_token"));

    assertError(password(BASIC, Map.of()), 400, "unauthorized_client");
  }

  @Test
  void passwordWithoutUsername_isInvalidRequest_notA500() {
    assertError(
        client.token(OidcTestFixtures.TENANT, BASIC,
            Map.of("grant_type", "password", "password", OidcTestFixtures.PASSWORD)),
        400, "invalid_request");
  }

  @Test
  void wrongResourceOwnerCredentials_isInvalidGrant() {
    loginGateway.whenValidate(() -> AuthenticationResult.wrongCredential(OidcTestFixtures.TENANT,
        OidcTestFixtures.USERNAME));

    assertError(password(BASIC, Map.of()), 400, "invalid_grant");
  }

  @Test
  void pendingSecondFactor_isMfaRequired_withMfaToken() {
    loginGateway.whenValidate(
        () -> AuthenticationResult.mfaRequired(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME));

    Response response = password(BASIC, Map.of());

    Assertions.assertEquals(403, response.statusCode());
    Assertions.assertEquals("mfa_required", response.jsonPath().getString("error"));
    Assertions.assertNotNull(response.jsonPath().getString("mfa_token"));
    assertNoStore(response);
  }

  @Test
  void codeWithoutCodeParameter_isInvalidRequest() {
    assertError(client.token(OidcTestFixtures.TENANT, BASIC,
        Map.of("grant_type", "authorization_code", "redirect_uri", OidcTestFixtures.REDIRECT_URI)),
        400, "invalid_request");
  }

  // ── 0.9 client authentication ─────────────────────────────────────────────

  @Test
  void clientSecretPost_isAccepted() {
    Response response = password(null, Map.of("client_id", OidcTestFixtures.CLIENT_ID,
        "client_secret", OidcTestFixtures.CLIENT_SECRET));

    Assertions.assertEquals(200, response.statusCode());
  }

  @Test
  void basicAndBodySecretTogether_isInvalidClient() {
    assertError(password(BASIC, Map.of("client_secret", OidcTestFixtures.CLIENT_SECRET)), 401,
        "invalid_client");
  }

  @Test
  void basicAndOtherBodyClientId_isInvalidClient() {
    assertError(password(BASIC, Map.of("client_id", OidcTestFixtures.WEB_CLIENT_ID)), 401,
        "invalid_client");
  }

  @Test
  void malformedBasic_isInvalidClient_notA500() {
    assertError(password("Basic not-base64!", Map.of()), 401, "invalid_client");
  }

  @Test
  void publicClient_cannotUseSecretGrants() {
    assertError(password(null, Map.of("client_id", OidcTestFixtures.CLIENT_ID)), 401,
        "invalid_client");
  }

  @Test
  void clientRegisteredForNone_cannotAuthenticateWithSecret() {
    assertError(password(
        OidcFlowClient.basic(OidcTestFixtures.SPA_CLIENT_ID, OidcTestFixtures.CLIENT_SECRET),
        Map.of()), 401, "invalid_client");
  }

  @Test
  void clientOfAnotherTenant_isInvalidClient() {
    assertError(client.token(OidcTestFixtures.TENANT,
        OidcFlowClient.basic("unknown-client", OidcTestFixtures.CLIENT_SECRET),
        Map.of("grant_type", "client_credentials")), 401, "invalid_client");
  }

  @Test
  void clientCredentials_withSecret_isIssued() {
    clientStoreGateway.setClientCredentialsScopes(java.util.List.of("orders:read"));
    Response response = client.token(OidcTestFixtures.TENANT, BASIC,
        Map.of("grant_type", "client_credentials", "scope", "orders:read"));

    Assertions.assertEquals(200, response.statusCode());
    Assertions.assertNull(response.jsonPath().getString("refresh_token"));
    assertNoStore(response);
  }

  // ── 0.13 revocation route ─────────────────────────────────────────────────

  @Test
  void revocation_isTheRfc7009Endpoint_andRequiresClientAuthentication() {
    Response anonymous =
        RestAssured.given().contentType(ContentType.URLENC).formParam("token", "whatever")
            .post("/oauth/openid/" + OidcTestFixtures.TENANT + "/revocation");
    Assertions.assertEquals(401, anonymous.statusCode());
    Assertions.assertEquals("invalid_client", anonymous.jsonPath().getString("error"));

    Response authenticated = RestAssured.given().contentType(ContentType.URLENC)
        .header("Authorization", BASIC).formParam("token", "whatever")
        .post("/oauth/openid/" + OidcTestFixtures.TENANT + "/revocation");
    Assertions.assertEquals(200, authenticated.statusCode());
    Assertions.assertEquals("no-store", authenticated.getHeader("Cache-Control"));
  }

  @Test
  void revocation_withoutForm_neverReachesThePreSessionHandler() {
    Response response =
        RestAssured.given().cookie("PRE_SESSION_ID", "pre-session").contentType(ContentType.JSON)
            .body("{}").post("/oauth/openid/" + OidcTestFixtures.TENANT + "/revocation");

    Assertions.assertEquals(415, response.statusCode());
  }

  @Test
  void revocation_revokesTheToken_forIntrospection() {
    String access = password(BASIC, Map.of()).jsonPath().getString("access_token");

    RestAssured.given().contentType(ContentType.URLENC)
        .formParam("client_id", OidcTestFixtures.CLIENT_ID)
        .formParam("client_secret", OidcTestFixtures.CLIENT_SECRET).formParam("token", access)
        .post("/oauth/openid/" + OidcTestFixtures.TENANT + "/revocation").then().statusCode(200);

    String jti = String.valueOf(decodeToken(access).get("jti"));
    Assertions.assertTrue(tokenRevocationGateway.isRevoked(jti, OidcTestFixtures.TENANT),
        "The JTI of the access token is in the revocation store");
  }
}
